<script setup lang="ts">
import { computed, ref } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { api } from '@/api/client'
type Payment={id:number;reference:string;amount:number;status:string};const payment=ref<number>();const msg=ref('');const err=ref('');const search=ref('');const payments=useQuery({queryKey:['payments'],queryFn:async()=>{const r=await api.get('/payments');return r.data.data?.data??r.data.data??[]}});const list=computed<Payment[]>(()=>((payments.data.value??[])as Payment[]).filter(item=>`${item.reference} ${item.status}`.toLowerCase().includes(search.value.toLowerCase())))
async function invoice(){try{if(!payment.value)throw Error('Select a payment.');const r=await api.get(`/payments/${payment.value}/invoice`);msg.value=`Invoice ${r.data.data.invoice_number}: ₱${r.data.data.amount}`}catch(e:any){err.value=e.message==='Select a payment.'?e.message:e.response?.data?.message??'Invoice not available.'}}async function recon(){try{const r=await api.get('/payments/reconciliation/summary');msg.value=`Paid: ₱${r.data.data.paid_amount}; pending: ₱${r.data.data.pending_amount}`}catch(e:any){err.value=e.response?.data?.message??'Reconciliation unavailable.'}}async function providers(){try{const r=await api.get('/payments/providers');msg.value=`Available providers: ${(r.data.data??r.data).map((item:any)=>item.name??item).join(', ')}`}catch(e:any){err.value=e.response?.data?.message??'Payment providers unavailable.'}}async function settlements(){try{const r=await api.get('/payments/settlements');const providers=(r.data.data.providers??[]).map((item:any)=>`${item.provider}: ₱${item.paid_amount}`).join(', ');msg.value=`Simulated settlements — paid: ₱${r.data.data.total_paid}. ${providers||'No provider events yet.'}`}catch(e:any){err.value=e.response?.data?.message??'Settlement feed unavailable.'}}</script>
<template><section class="panel membership-form payment-form"><h2>Payment operations</h2><form @submit.prevent="invoice"><label>Find payment<input v-model="search" placeholder="Reference or status"/></label><label>Payment<select v-model.number="payment"><option :value="undefined">Select payment</option><option v-for="item in list" :key="item.id" :value="item.id">{{item.reference}} · ₱{{item.amount}} · {{item.status}}</option></select></label><button class="secondary-button">View invoice</button><button class="table-button" type="button" @click="recon">Reconciliation summary</button><button class="table-button" type="button" @click="settlements">Mock settlement feed</button><button class="table-button" type="button" @click="providers">Available providers</button></form><p v-if="msg" class="action-message success">{{msg}}</p><p v-if="err" class="action-message error">{{err}}</p></section></template>
